window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[362]={"id":"362","numero":362,"titre":"Prothèses et ostéosynthèse","objectifs":[{"id":"362-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une ostéosynthèse, d’une prothèse","contenu":"<p>Deux gestes orthopédiques distincts : l'<span class=\"kw-def\">ostéosynthèse</span> <strong>fixe une fracture</strong> (traitement conservateur de l'os), la <span class=\"kw-def\">prothèse</span> <strong>remplace une articulation</strong> (traitement non conservateur).</p>\n\n      <h4 class=\"kw-def\"><span class=\"kw-ttt\">Ostéosynthèse</span> — définition</h4>\n      <p>Contention <strong>interne</strong> d'une fracture après <span class=\"kw-ttt\">réduction</span>. Deux objectifs :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Assurer une contention interne</span> après <span class=\"kw-ttt\">réduction</span> du foyer de fracture</li>\n        <li><span class=\"kw-ttt\">Permettre une mobilisation rapide</span> du membre opéré, en libérant <span class=\"kw-clinique\">les</span> articulations sus- et sous-jacentes</li>\n      </ul>\n      <p>La <strong><span class=\"kw-ttt\">réduction</span></strong> préalable se fait selon deux modalités :</p>\n      <table >\n        <thead><tr><th>Réduction</th><th>Principe</th><th>Conséquence</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>À foyer ouvert</strong></td>\n            <td>Abord chirurgical, <span class=\"kw-ttt\">manipulation directe</span> des fragments</td>\n            <td><span class=\"kw-ttt\">Réduction</span> <span class=\"kw-clinique\">plus anatomique</span>, mais <span class=\"kw-alerte\">dépériostage</span> et <span class=\"kw-alerte\">fuite de l'hématome péri-fracturaire</span></td>\n          </tr>\n          <tr>\n            <td><strong>À foyer fermé</strong></td>\n            <td><span class=\"kw-ttt\">Réduction</span> par <span class=\"kw-ttt\">manœuvres externes</span> ; abord à distance du foyer</td>\n            <td><span class=\"kw-clinique\">Conserve l'hématome péri-fracturaire</span> (favorable à la consolidation)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\"><span class=\"kw-clinique\">Les</span> <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> g</span>rands types d'<span class=\"kw-ttt\">ostéosynthèse</span></h4>\n      <table >\n        <thead><tr><th></th><th>Latéro-corticale</th><th>Centromédullaire</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Matériel</strong></td><td><span class=\"kw-ttt\">Plaque</span> ou <span class=\"kw-ttt\">vissage simple</span></td><td><span class=\"kw-ttt\">Clou</span></td></tr>\n          <tr><td><strong>Foyer</strong></td><td>Ouvert</td><td>Fermé (manœuvres externes)</td></tr>\n          <tr><td><strong>Anatomie</strong></td><td><span class=\"kw-ttt\">Réduction</span> <span class=\"kw-clinique\">la plus anatomique</span></td><td><span class=\"kw-ttt\">Réduction</span> imparfaite (<span class=\"kw-clinique\">chevauchement possible</span>)</td></tr>\n          <tr><td><strong>Périoste / hématome</strong></td><td><span class=\"kw-alerte\">Dépériostage</span> + fuite de l'hématome</td><td>Évite la fuite de l'hématome</td></tr>\n          <tr><td><strong>Indication type</strong></td><td>Fracture <span class=\"kw-clinique\">métaphysaire</span> ++</td><td>Fracture <span class=\"kw-clinique\">diaphysaire</span> ++ (fémur, humérus, tibia)</td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Fixation externe</strong> : système rigide <span class=\"kw-def\">non implanté</span>, fixé sur des fiches insérées de part et d'autre du foyer. Indications : <span class=\"kw-clinique\">fractures ouvertes</span> (couverture cutanée impossible/douteuse), état général précaire, <span class=\"kw-ttt\">damage control</span> (en attente d'un clou/<span class=\"kw-clinique\">plaque</span>)</li>\n        <li><strong>Autres</strong> : <span class=\"kw-ttt\">ostéosynthèse</span> <span class=\"kw-ttt\">percutanée</span> par broches/vis (incisions millimétriques, <span class=\"kw-clinique\">conserve l'hématome</span>) ; <span class=\"kw-ttt\">cerclage</span> associé aux broches en hauban (fractures <span class=\"kw-clinique\">spiroïdes</span>)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Clou verrouillé.</strong> Le clou seul ne bloque pas la rotation. Dans <span class=\"kw-clinique\">les</span> fractures <span class=\"kw-clinique\">comminutives</span>, on ajoute des vis percutanées perpendiculaires (<span class=\"kw-ttt\">clou verrouillé</span>) : stabilité rotatoire + maintien de la longueur, au prix d'un montage statique (<span class=\"kw-alerte\">risque accru de pseudarthrose</span>).</div>\n\n      <h4 class=\"kw-def\">Prothèse — définition</h4>\n      <p>L'<span class=\"kw-def\">arthroplastie</span> consiste à remplacer une articulation, de façon <strong>totale ou partielle</strong> = <span class=\"kw-alerte\">traitement non conservateur</span>.</p>\n      <ul>\n        <li><strong>Composition</strong> :\n          <ul>\n            <li><span class=\"kw-def\">Pièces fixes</span> : scellées ou impactées dans l'os</li>\n            <li><span class=\"kw-def\">Pièces mobiles</span> (de connexion) : forment le <strong>couple de frottement</strong> ; siège du phénomène d'<span class=\"kw-clinique\">usure</span> ; <span class=\"kw-clinique\">changeables sans desceller les pièces fixes</span></li>\n          </ul>\n        </li>\n        <li><strong>Indications principales</strong> :\n          <ul>\n            <li><span class=\"kw-etio\">Arthrose</span> primitive ou secondaire, quand <span class=\"kw-clinique\">les</span> traitements médicaux et conservateurs sont dépassés</li>\n            <li>Fracture à <span class=\"kw-etio\">risque de nécrose secondaire</span></li>\n            <li>Fracture articulaire trop <span class=\"kw-etio\">comminutive</span> chez le <span class=\"kw-clinique\">sujet âgé</span></li>\n          </ul>\n        </li>\n        <li><strong><span class=\"kw-def\">Épidémiologie</span></strong> (parmi <span class=\"kw-clinique\">les</span> interventions les plus pratiquées en France) :\n          <ul>\n            <li><span class=\"kw-chiffre\">Hanche</span> : ~170 000/an — survie à<span class=\"kw-chiffre\"> 20 ans</span> <strong><span class=\"kw-chiffre\">96 %</span></strong></li>\n            <li><span class=\"kw-chiffre\">Genou</span> : ~100 000/an — survie à<span class=\"kw-chiffre\"> 20 ans</span> <strong><span class=\"kw-chiffre\">94 %</span></strong></li>\n            <li><span class=\"kw-chiffre\">Épaule</span>, puis autres localisations (plus rares)</li>\n          </ul>\n        </li>\n      </ul>","frequence":0,"liens":[{"href":"https://radiopaedia.org/cases/humerus-fracture-before-and-after-osteosynthesis","label":"Radiopaedia — Fracture avant/après ostéosynthèse"}]},{"id":"362-2","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître la physiologie de la consolidation osseuse normale et pathologique","contenu":"<h4 class=\"kw-def\">1 · Consolidation normale — deux voies selon l'écart</h4>\n      <table >\n        <thead><tr><th>Voie</th><th>Conditions</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Remodelage Haversien direct</strong><br>(écart faible, montage rigide)</td>\n            <td><span class=\"kw-bio\">&lt; 10 µm</span> : « <em><span class=\"kw-def\">contact</span> healing</em> », <span class=\"kw-clinique\">les</span> cônes de résorption traversent directement le trait<br><span class=\"kw-bio\">10 µm – 1 mm</span> : « <em>gap healing</em> », les ostéoblastes comblent les cavités</td>\n            <td><span class=\"kw-alerte\">Pas de cal osseux</span> ❌ · consolidation <span class=\"kw-clinique\">rapide (~4 semaines)</span> · ex<span class=\"kw-chiffre\">ige</span> une <span class=\"kw-ttt\">immobilisation stricte</span> (<span class=\"kw-ttt\">ostéosynthèse</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Consolidation par cal</strong><br>(ossification endochondrale + membraneuse)</td>\n            <td>Écart inter-fragmentaire plus important</td>\n            <td>Passe par <span class=\"kw-clinique\">les</span> <strong>4 phases</strong> ci-dessous · immobilisation <span class=\"kw-ttt\">relative</span> suffisante</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\"><span class=\"kw-clinique\">Les</span> 4 phases de la consolidation par cal</h4>\n      <table >\n        <thead><tr><th>Phase</th><th>Délai</th><th>Évènements clés</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1 · <span class=\"kw-etio\">Inflammatoire</span></strong></td>\n            <td><span class=\"kw-chiffre\">J0–J7</span></td>\n            <td><span class=\"kw-alerte\">Rupture</span> vasculaire (centromédullaire + périoste) → <span class=\"kw-clinique\">hématome</span> + réaction <span class=\"kw-etio\">inflammatoire</span> locale (<span class=\"kw-bio\">DAMP</span>) → afflux de PNN/macrophages (résorption) et de <span class=\"kw-bio\">cellules mésenchymateuses pluripotentes</span> → <span class=\"kw-clinique\">tissu de granulation</span> (1er pont d'union)</td>\n          </tr>\n          <tr>\n            <td><strong>2 · Cal mou</strong></td>\n            <td><span class=\"kw-chiffre\">J7–J30</span></td>\n            <td>Prolifération des cellules mésenchymateuses → <span class=\"kw-bio\">différenciation</span> en <span class=\"kw-bio\">chondroblastes</span> → <span class=\"kw-clinique\">cal fibro-cartilagineux (cal mou)</span> ; ossification membraneuse périostée (collagène I)</td>\n          </tr>\n          <tr>\n            <td><strong>3 · Cal dur</strong></td>\n            <td><span class=\"kw-chiffre\">J30–J60</span></td>\n            <td>Cal <span class=\"kw-imagerie\">radiologiquement visible dès J30</span> ; <span class=\"kw-clinique\">les</span> ostéoblastes envahissent la matrice fibro-cartilagineuse → matrice osseuse minéralisée → <span class=\"kw-clinique\">pont osseux</span> + cal périosté. <strong>Critère radiologique de consolidation (score RUST)</strong> : présence d'un pont osseux sur <span class=\"kw-chiffre\">3 des 4 corticales</span> visibles (faces antérieure, postérieure, interne, externe) sur les incidences de face et de profil.</td>\n          </tr>\n          <tr>\n            <td><strong>4 · Remodelage</strong></td>\n            <td><span class=\"kw-chiffre\">J30–M18</span></td>\n            <td>Loi de Wolff : zones <span class=\"kw-clinique\">en compression</span> s'ossifient, zones <span class=\"kw-clinique\">en traction</span> se résorbent → remodelage jusqu'à la forme définitive (<span class=\"kw-chiffre\">18–24 mois</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">2 · Facteurs influençant la consolidation</h4>\n      <table >\n        <thead><tr><th>Liés au malade</th><th>Liés à la fracture</th><th>Liés au traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <ul>\n                <li><span class=\"kw-etio\">Âge</span> (↓ capacités physiologiques)</li>\n                <li><span class=\"kw-etio\">Tabac (nicotine)</span> : ↓ néovascularisation, inhibe <span class=\"kw-clinique\">les</span> protéines ostéo-inductrices</li>\n                <li><span class=\"kw-etio\">Diabète</span> et troubles métaboliques</li>\n                <li><span class=\"kw-etio\">Anémie / hypovolémie</span></li>\n                <li><span class=\"kw-etio\">AINS, corticoïdes</span> (↓ réponse <span class=\"kw-etio\">inflammatoire</span> initiale)</li>\n                <li>Atteinte de la microvascularisation (<span class=\"kw-etio\">alcool</span>, <span class=\"kw-clinique\">irradiation</span>, <span class=\"kw-ttt\">chimiothérapie</span>)</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Favorable</span> : trait <strong>transversal</strong> ; fracture <strong>épiphysaire / métaphysaire</strong></li>\n                <li><span class=\"kw-alerte\">Péjoratif</span> : trait <strong>oblique</strong> ; fracture <strong>diaphysaire</strong> ; fracture <strong>ouverte</strong>, lésions des parties molles, <span class=\"kw-clinique\">lésion</span> artérielle</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"kw-ttt\">Immobilisation insuffisante</span> (totale/stricte pour le remodelage direct, relative pour le cal)</li>\n                <li><span class=\"kw-alerte\">Écart inter-fragmentaire</span> trop important (<span class=\"kw-ttt\">pontage</span> des contraintes)</li>\n                <li><span class=\"kw-alerte\">Incarcération de tissu mou</span></li>\n                <li><span class=\"kw-ttt\">AINS</span> post-op (altèrent ostéo-induction et chimiotaxie)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">3 · Consolidation pathologique</h4>\n      <div class=\"callout callout-info\"><strong>Cal vicieux</strong> — consolidation en <span class=\"kw-alerte\">mauvaise position</span> (non anatomique).\n        <ul>\n          <li><strong>Causes</strong> : défaut de <span class=\"kw-ttt\">réduction</span> initiale, déplacement secondaire</li>\n          <li><strong>Plans</strong> : <span class=\"kw-clinique\">les</span> 3 plans de l'espace — <span class=\"kw-clinique\">angulation</span>, <span class=\"kw-clinique\">rotation (décalage)</span>, <span class=\"kw-clinique\">raccourcissement</span></li>\n          <li><strong>Risque</strong> : un cal vicieux <span class=\"kw-alerte\">articulaire</span> → incongruence → <span class=\"kw-alerte\">arthrose précoce</span></li>\n          <li><strong>Correction</strong> : <span class=\"kw-ttt\">ostéotomie de réaxation</span> (si mal supporté ou sujet jeune)</li>\n        </ul>\n      </div>\n\n      <p><strong>Absence de consolidation</strong> — distinguer retard et pseudarthrose selon le délai :</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Délai</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Retard de consolidation</strong></td><td>entre <span class=\"kw-chiffre\">2× le délai habituel</span> (≈<span class=\"kw-chiffre\"> 3 mois</span>) et <span class=\"kw-chiffre\">6 mois</span></td><td>Consolidation encore possible</td></tr>\n          <tr><td><strong>Pseudarthrose</strong></td><td><span class=\"kw-chiffre\">≥ 6 mois</span></td><td>Absence définitive de consolidation</td></tr>\n        </tbody>\n      </table>\n      <p><em>Délais habituels de référence :</em> mandibule ~6 sem (45 j) · radius ~6 sem · fémur trochantérien ~40 j, cervical ~<span class=\"kw-chiffre\">4 mois</span>. <strong>Diagnostic</strong> : douleur à l'appui + mobilité du foyer (pseudarthrose lâche) ; <span class=\"kw-imagerie\">RX ou TDM</span> = persistance de la solution de continuité.</p>\n\n      <div class=\"callout callout-danger\"><strong>Pseudarthrose septique — dogme.</strong> Une cause <span class=\"kw-alerte\">infectieuse</span> doit être évoquée <strong>en priorité dans tous <span class=\"kw-clinique\">les</span> cas</strong>, <span class=\"kw-alerte\">même en l'absence de syndrome infectieux</span>. Le bilan paraclinique recherche systématiquement un germe. Traitement médico-chirurgical : <span class=\"kw-ttt\">antibiothérapie</span> (probabiliste puis adaptée aux prélèvements per-opératoires), excision des tissus infectés, <span class=\"kw-ttt\">changement de l'ostéosynthèse</span>, reconstruction osseuse (greffe).</div>\n\n      <table >\n        <thead><tr><th>Pseudarthrose aseptique</th><th>Imagerie</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Atrophique</strong> (absence de cal)</td>\n            <td>Extrémités <span class=\"kw-imagerie\">effilées</span>, image en <span class=\"kw-imagerie\">« queue de radis »</span></td>\n            <td><span class=\"kw-alerte\">Défaut de vascularisation</span> : dépériostage agressif, écart trop important, fragment dévascularisé</td>\n          </tr>\n          <tr>\n            <td><strong>Hypertrophique</strong> (appositions périostées)</td>\n            <td>Image en <span class=\"kw-imagerie\">« patte d'éléphant »</span> (cal circulaire volumineux qui ne fusionne pas)</td>\n            <td><span class=\"kw-alerte\">Mobilité résiduelle</span> du foyer (<span class=\"kw-ttt\">ostéosynthèse</span> instable)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Traitement de la pseudarthrose aseptique</strong> :</p>\n      <ul>\n        <li>PEC des <span class=\"kw-ttt\">facteurs affectant la consolidation</span> (arrêt du tabac, équilibration du <span class=\"kw-etio\">diabète</span>…)</li>\n        <li><span class=\"kw-ttt\">Injection de moelle osseuse autologue</span> dans le foyer (cellules progénitrices + protéines ostéo-inductrices)</li>\n        <li><span class=\"kw-ttt\">Chirurgie</span> si échec : excision du tissu interposé + remise en <span class=\"kw-def\">contact</span>, <span class=\"kw-ttt\">modification de l'ostéosynthèse</span>, <span class=\"kw-ttt\">auto-greffe osseuse</span> ; <span class=\"kw-ttt\">PTH</span> si pseudarthrose du col fémoral</li>\n      </ul>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/fracture-malunion","label":"Radiopaedia — Cal vicieux (malunion)"},{"href":"https://radiopaedia.org/articles/fracture-non-union-1","label":"Radiopaedia — Pseudarthrose (non-union)"}]},{"id":"362-3","rang":"B","rubrique":"Prise en charge","titre":"Connaître les complications des ostéosynthèses","contenu":"<p>On distingue <span class=\"kw-clinique\">les</span> complications <strong>précoces</strong> (per/post-opératoires) et <strong>tardives</strong> (liées à la consolidation).</p>\n\n      <table >\n        <thead><tr><th>Précoces</th><th>Tardives</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Infection du site opératoire</span> — <strong>la plus redoutée</strong></li>\n                <li><span class=\"kw-alerte\">TVP / embolie pulmonaire</span></li>\n                <li><span class=\"kw-alerte\">Embolie graisseuse</span></li>\n                <li><span class=\"kw-alerte\">Syndrome des loges</span> (syndrome compartimental)</li>\n                <li><span class=\"kw-clinique\">Déplacement secondaire</span> : défaut de rigidité du montage ou os de mauvaise qualité → nécessite fréquemment une <span class=\"kw-ttt\">reprise chirurgicale</span></li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Pseudarthrose</span> (septique ou non)</li>\n                <li><span class=\"kw-alerte\">Infection ostéo-articulaire post-fracture</span> : <strong>aiguë</strong> si &lt; <span class=\"kw-chiffre\">4 semaines</span> post-opératoires ; <strong>chronique</strong> au-delà de <span class=\"kw-chiffre\">4 semaines</span> (certaines définitions retiennent &gt; <span class=\"kw-chiffre\">3 mois</span>). Voie de contamination : directe (peropératoire, plaie ouverte, contiguïté) ou <strong>hématogène</strong> (dissémination bactériémique à partir d'un foyer à distance — surtout <span class=\"kw-etio\">ostéomyélite de l'enfant</span> [métaphyse hypervascularisée] et <span class=\"kw-etio\">spondylodiscite de l'adulte</span>).</li>\n                <li><span class=\"kw-clinique\">Cal vicieux</span></li>\n                <li><span class=\"kw-clinique\">SDRC de type 1</span> (algodystrophie)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><strong>Repère.</strong> L'<span class=\"kw-alerte\">infection</span> et le <span class=\"kw-alerte\">déplacement secondaire</span> dominent <span class=\"kw-clinique\">les</span> complications précoces ; la <span class=\"kw-alerte\">pseudarthrose</span> et le <span class=\"kw-clinique\">cal vicieux</span> dominent les complications tardives (cf. objectif « consolidation pathologique »).</div>\n\n      <h4 class=\"kw-def\"><span class=\"kw-def\">Surveillance</span> post-opératoire (rappel)</h4>\n      <ul>\n        <li><strong>Post-op immédiat</strong> : pansement régulier jusqu'à cicatrisation ; <span class=\"kw-def\">surveillance</span> clinique (douleur, <span class=\"kw-clinique\">fièvre</span>, constantes, cicatrice, signes d'infection, signes de TVP, syndrome des loges) ; <span class=\"kw-imagerie\">RX post-op</span> (position du matériel, qualité de <span class=\"kw-ttt\">réduction</span>, absence de déplacement secondaire)</li>\n        <li><strong>Consultations de contrôle</strong> (ex. KB : <span class=\"kw-chiffre\">J2</span>, J7, J15, J21, J45, J90) : reprise d'appui sans douleur, <span class=\"kw-imagerie\">signes RX de consolidation</span> (cal visible dès J30)</li>\n        <li><strong>Ablation du matériel</strong> : <span class=\"kw-alerte\">non obligatoire</span> ❌ ; seulement si consolidation complète (<span class=\"kw-chiffre\">12–18 mois</span>) et si gêne / trouble fonctionnel / infection. Risques : infection, <span class=\"kw-alerte\">fracture itérative</span> (ex. trou de vis)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 365 — <span class=\"kw-def\">Surveillance</span> d'un malade sous plâtre (syndrome des loges) · 330 — Prescription et surveillance des médicaments hors anti-<span class=\"kw-etio\">infectieux</span> (anti-thrombotiques : TVP/EP)</em></p>","frequence":0},{"id":"362-4","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir rechercher les complications urgentes des ostéosynthèses (clinique, biologie, indication d’imagerie)","contenu":"<p>Parmi <span class=\"kw-clinique\">les</span> complications précoces, quatre sont des <span class=\"kw-alerte\">urgences</span> à dépister systématiquement en post-opératoire : <strong>infection</strong>, <strong>syndrome des loges</strong>, <strong>embolie graisseuse</strong> et <strong>maladie thrombo-<span class=\"kw-etio\">embolique</span></strong>. La recherche associe clinique, biologie et imagerie ciblée.</p>\n\n      <table >\n        <thead><tr><th><span class=\"kw-alerte\">Urgence</span></th><th>Clinique</th><th>Biologie</th><th>Imagerie</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Infection du site opératoire</strong></span> (la plus redoutée) — <strong>aiguë</strong> &lt; <span class=\"kw-chiffre\">4 semaines</span> post-op, <strong>chronique</strong> au-delà (&gt; <span class=\"kw-chiffre\">3 mois</span> selon certaines classifications).</td>\n            <td><span class=\"kw-clinique\">Fièvre</span>, douleur, cicatrice <span class=\"kw-etio\">inflammatoire</span>, écoulement, désunion</td>\n            <td><span class=\"kw-bio\">NFS, CRP</span> ; <span class=\"kw-bio\">prélèvements / hémocultures</span> (germe)</td>\n            <td><span class=\"kw-imagerie\">RX</span> de contrôle ; imagerie selon le contexte</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Syndrome des loges</strong></span></td>\n            <td><span class=\"kw-clinique\">Recrudescence de douleur</span> post-opératoire <strong>non calmée par <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">antalgiques</span></strong>, tension de loge, douleur à l'étirement passif</td>\n            <td>(<span class=\"kw-bio\">CPK</span>) — diagnostic avant tout <span class=\"kw-clinique\">clinique</span></td>\n            <td>Mesure des <span class=\"kw-imagerie\">pressions de loge</span> si doute (ne doit pas retarder la <span class=\"kw-ttt\">chirurgie</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Embolie graisseuse</strong></span></td>\n            <td><span class=\"kw-alerte\">Détresse</span> respiratoire, signes neurologiques, <span class=\"kw-clinique\">purpura</span> (contexte de fracture d'os long)</td>\n            <td>Bilan d'<span class=\"kw-bio\">hypoxémie</span></td>\n            <td>Imagerie thoracique selon le tableau</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>TVP / embolie pulmonaire</strong></span></td>\n            <td><span class=\"kw-clinique\">Signes de TVP</span> du membre, signes d'EP</td>\n            <td><span class=\"kw-bio\">D-dimères</span> selon le contexte</td>\n            <td><span class=\"kw-imagerie\">Écho-Doppler veineux</span> ; <span class=\"kw-imagerie\">angio-TDM</span> si suspicion d'EP</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Déplacement secondaire</strong></span></td>\n            <td>Douleur, déformation, perte de <span class=\"kw-ttt\">réduction</span></td>\n            <td>—</td>\n            <td><span class=\"kw-imagerie\">RX</span> de contrôle (montage, <span class=\"kw-ttt\">réduction</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong>Réflexe syndrome des loges.</strong> Toute <span class=\"kw-alerte\">douleur post-opératoire non calmée par les antalgiques</span> impose d'éliminer un syndrome compartimental en <span class=\"kw-alerte\">urgence</span> : c'est un diagnostic <strong>clinique</strong> qui ne doit jamais être retardé par <span class=\"kw-clinique\">les</span> examens complémentaires.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 365 — <span class=\"kw-def\">Surveillance</span> d'un malade sous plâtre · 359 — <span class=\"kw-alerte\">Détresse</span> respiratoire aiguë (embolie graisseuse)</em></p>","frequence":0},{"id":"362-5","rang":"B","rubrique":"Prise en charge","titre":"Connaître les complications des prothèses","contenu":"<p>Vue d'ensemble des complications prothétiques. L'<span class=\"kw-alerte\">infection de prothèse</span> est la plus redoutée ; l'<span class=\"kw-clinique\">usure</span> est le point de départ d'une cascade fréquente (usure → ostéolyse → descellement).</p>\n\n      <div class=\"callout callout-info\"><strong>Cascade de l'usure.</strong> Particules du couple de frottement → <span class=\"kw-clinique\">réaction inflammatoire</span> (macrophages dépassés) → <span class=\"kw-alerte\">ostéolyse périprothétique</span> → <span class=\"kw-alerte\">descellement</span>. L'usure en elle-même est <strong>indolore</strong> ❌ ; ce sont ses complications qui deviennent symptomatiques.</div>\n\n      <h4 class=\"kw-def\">Usure &amp; descellement</h4>\n      <table >\n        <thead><tr><th></th><th>Usure</th><th>Descellement</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Définition</strong></td><td>Émission de particules par le couple de frottement</td><td><span class=\"kw-alerte\">Faillite de la fixation</span> de la prothèse à l'os</td></tr>\n          <tr><td><strong>Cause</strong></td><td>Mouvements répétés</td><td>Majoritairement l'<span class=\"kw-clinique\">usure</span> ; aussi cause <span class=\"kw-alerte\">septique</span>, erreur de pose, mauvaise qualité osseuse</td></tr>\n          <tr><td><strong>Clinique</strong></td><td><span class=\"kw-clinique\">Indolore</span></td><td><span class=\"kw-clinique\">Douleur</span> + altération fonctionnelle</td></tr>\n          <tr><td><strong>Imagerie</strong></td><td>Dépistée à la <span class=\"kw-def\">surveillance</span></td><td><span class=\"kw-imagerie\">Liseré périprothétique évolutif</span> + <span class=\"kw-imagerie\">ostéolyse</span></td></tr>\n          <tr><td><strong>CAT</strong></td><td><span class=\"kw-def\">Surveillance</span> radiologique</td><td><span class=\"kw-ttt\">Changement des implants</span></td></tr>\n        </tbody>\n      </table>\n      <p><em>Prévention :</em> couples de frottement <span class=\"kw-ttt\">céramique-céramique</span> ou <span class=\"kw-ttt\">céramique-polyéthylène réticulé</span> → moins de particules, moins de descellement.</p>\n\n      <h4 class=\"kw-def\">Luxation de prothèse</h4>\n      <ul>\n        <li><strong>Définition</strong> : perte de <span class=\"kw-def\">contact</span> entre <span class=\"kw-clinique\">les</span> implants — la <span class=\"kw-clinique\">prothèse de hanche</span> est la plus touchée</li>\n        <li><strong>Causes</strong> : <span class=\"kw-alerte\">infection</span> (à évoquer de principe, surtout si précoce), mouvement luxant (hanche : <em>postérieure</em> = flexion-adduction-rotation interne ; <em>antérieure</em> = extension-rotation externe), erreur de positionnement ou de tension musculaire, usure</li>\n        <li><strong>Traitement</strong> : <span class=\"kw-ttt\">réduction sous AG en urgence</span> ; si récidive → <span class=\"kw-imagerie\">TDM</span> (infection, positionnement) ; si instabilité → <span class=\"kw-ttt\">changement de prothèse</span></li>\n        <li><em>Prévention</em> : prothèses à <span class=\"kw-ttt\">double mobilité</span> chez <span class=\"kw-clinique\">les</span> sujets à risque (reprise, <span class=\"kw-etio\">obésité</span>, pathologie neurologique…)</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Raideur</h4>\n      <ul>\n        <li><strong>Définition</strong> : limitation <span class=\"kw-clinique\">fixée et permanente</span> des amplitudes articulaires (risque ultime : <span class=\"kw-alerte\">ankylose</span>)</li>\n        <li><strong>FR</strong> : sujet âgé, <span class=\"kw-clinique\">immobilisation prolongée</span>, fracture articulaire, rééducation absente ou trop agressive, malposition des implants</li>\n        <li><strong>PEC</strong> : <span class=\"kw-ttt\">rééducation</span> ; <span class=\"kw-ttt\">mobilisation sous AG</span> (avant la 6ᵉ semaine) ; <span class=\"kw-ttt\">arthrolyse arthroscopique</span> (à partir du 3ᵉ mois) ; changement de prothèse</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Autres complications</h4>\n      <table >\n        <thead><tr><th>Complication</th><th>Points clés</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Fracture sur prothèse</strong> (péri-prothétique)</td><td>De plus en plus fréquente (âge + nombre de prothèses). Traitement chirurgical : <span class=\"kw-ttt\">ostéosynthèse</span> si prothèse scellée + capital osseux suffisant, sinon <span class=\"kw-ttt\">changement de prothèse</span></td></tr>\n          <tr><td><strong>Paralysie</strong></td><td>Nerf <span class=\"kw-def\">sciatique</span> (<span class=\"kw-bio\">PTH</span>), nerf <span class=\"kw-def\">axillaire</span> (prothèse d'épaule) ; <span class=\"kw-clinique\">lésion</span> tronculaire ou radiculaire (étirement). Le plus souvent <span class=\"kw-clinique\">régressive</span></td></tr>\n          <tr><td><strong>Inégalité de longueur</strong></td><td><span class=\"kw-alerte\">1ʳᵉ cause de litige</span> patient-chirurgien. Gênante après <span class=\"kw-chiffre\">5 mm</span> d'allongement, fautive après <span class=\"kw-chiffre\">1 cm</span>. Un <span class=\"kw-clinique\">raccourcissement est mieux toléré</span> qu'un allongement</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">Rupture</span> d'implant</strong></td><td>Exceptionnelle → <span class=\"kw-ttt\">changement prothétique</span> + <span class=\"kw-ttt\">déclaration de matériovigilance</span></td></tr>\n          <tr><td><strong>ALVAL / métallose</strong></td><td><span class=\"kw-ci\">Allergie</span> à un composant (chrome, cobalt, molybdène, nickel) : douleur, inflammation, épanchement stérile. Métallose : libération massive de particules métalliques (usure/malposition) → lésions osseuses et l<span class=\"kw-chiffre\">iga</span>mentaires</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Infection de prothèse</strong></span></td><td><strong>La plus redoutée</strong> (voir objectif « complications urgentes »)</td></tr>\n          <tr><td><strong>MTEV</strong></td><td><span class=\"kw-alerte\">TVP / embolie pulmonaire</span></td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments hors anti-<span class=\"kw-etio\">infectieux</span> (anti-thrombotiques : prévention TVP/EP) · 128 — Ostéopathie fragilisante (qualité osseuse)</em></p>","frequence":3,"liens":[{"href":"https://radiopaedia.org/articles/aseptic-loosening-of-hip-joint-replacements","label":"Radiopaedia — Descellement aseptique"},{"href":"https://radiopaedia.org/articles/hip-dislocation","label":"Radiopaedia — Luxation de hanche"}]},{"id":"362-6","rang":"A","rubrique":"Prise en charge","titre":"Savoir rechercher les complications urgentes des prothèses (clinique, biologie, indication d’imagerie)","contenu":"<p>Trois situations imposent une prise en charge <span class=\"kw-alerte\">urgente</span> : l'<strong>infection de prothèse</strong>, la <strong>luxation</strong> et la <strong>maladie thrombo-<span class=\"kw-etio\">embolique</span></strong>. La <strong>fracture péri-prothétique</strong> relève aussi de l'<span class=\"kw-alerte\">urgence</span> chirurgicale. Démarche : clinique → biologie → imagerie ciblée.</p>\n\n      <table >\n        <thead><tr><th>Urgence</th><th>Clinique</th><th>Biologie</th><th>Imagerie</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Infection de prothèse</strong></span> (la plus redoutée)</td>\n            <td><span class=\"kw-clinique\">Douleur</span>, <span class=\"kw-clinique\">fièvre</span>, signes inflammatoires locaux, écoulement / <span class=\"kw-clinique\">fistule</span> ; à évoquer <strong>de principe</strong> devant une luxation précoce</td>\n            <td><span class=\"kw-bio\">NFS, CRP</span> ; <span class=\"kw-bio\">ponction articulaire</span> + prélèvements / <span class=\"kw-bio\">hémocultures</span> (documentation du germe)</td>\n            <td><span class=\"kw-imagerie\">RX</span> (liseré, ostéolyse) ; <span class=\"kw-imagerie\">TDM séquence MARS</span> en cas de <span class=\"kw-clinique\">lésion</span> douteuse</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Luxation de prothèse</strong></span></td>\n            <td>Impotence brutale, <span class=\"kw-clinique\">attitude vicieuse</span> du membre, douleur (hanche ++)</td>\n            <td>(bilan pré-AG) ; <span class=\"kw-bio\">éliminer une infection</span> si récidive</td>\n            <td><span class=\"kw-imagerie\">RX</span> (diagnostic) ; <span class=\"kw-imagerie\">TDM</span> si récidive (positionnement, infection)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Fracture péri-prothétique</strong></span></td>\n            <td>Traumatisme + douleur/déformation en regard d'une pièce</td>\n            <td><span class=\"kw-def\">Bilan pré-opératoire</span></td>\n            <td><span class=\"kw-imagerie\">RX</span> ± <span class=\"kw-imagerie\">TDM</span> (descellement associé, capital osseux)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>TVP / embolie pulmonaire</strong></span></td>\n            <td>Signes de TVP du membre opéré, signes d'EP</td>\n            <td><span class=\"kw-bio\">D-dimères</span> selon le contexte</td>\n            <td><span class=\"kw-imagerie\">Écho-Doppler veineux</span> ; <span class=\"kw-imagerie\">angio-TDM</span> si suspicion d'EP</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong>Conduites urgentes.</strong> Une <span class=\"kw-alerte\">luxation de prothèse</span> = <span class=\"kw-ttt\">réduction par manœuvre externe sous AG en urgence</span>. Toute <span class=\"kw-alerte\">infection</span> ou luxation précoce impose de <strong>documenter le germe</strong> (<span class=\"kw-ttt\">ponction</span>/prélèvements) avant <span class=\"kw-ttt\">antibiothérapie</span>. La récidive ou l'instabilité conduit au <span class=\"kw-ttt\">changement de prothèse</span>.</div>\n\n      <h4 class=\"kw-def\"><span class=\"kw-def\">Surveillance</span> régulière (<span class=\"kw-def\">dépistage</span>)</h4>\n      <ul>\n        <li><span class=\"kw-def\">Suivi</span> <span class=\"kw-ttt\">multidisciplinaire</span> (chirurgien, médecin traitant, IDE, kiné) ; HAS : suivi <strong>annuel <span class=\"kw-chiffre\">5 ans</span></strong> puis <strong>biannuel</strong></li>\n        <li><strong>Clinique</strong> : signes <span class=\"kw-etio\">infectieux</span>, scores fonctionnels, mobilités articulaires</li>\n        <li><strong>Imagerie</strong> : recherche de descellement → <span class=\"kw-imagerie\">liseré périprothétique</span> + <span class=\"kw-imagerie\">ostéolyse</span> sur RX standard ; <span class=\"kw-imagerie\">TDM séquence MARS</span> (réduit <span class=\"kw-clinique\">les</span> artéfacts métalliques) si <span class=\"kw-clinique\">lésion</span> douteuse</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 156 — Infection ostéo-articulaire (infection de prothèse) · 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments hors anti-<span class=\"kw-etio\">infectieux</span> (anti-thrombotiques)</em></p>","frequence":3,"liens":[{"href":"https://radiopaedia.org/articles/hip-arthroplasty-overview","label":"Radiopaedia — Hip arthroplasty (overview)"}]}],"astuces":[],"strategie":{"urgence":"<p><strong>Luxation de prothèse :</strong> <span class=\"kw-ttt\">réduction par manœuvre externe sous anesthésie générale</span> en <span class=\"kw-alerte\">urgence</span>.<br><strong>Syndrome des loges :</strong> <span class=\"kw-alerte\">urgence chirurgicale</span> devant une <span class=\"kw-clinique\">douleur post-opératoire non calmée par les antalgiques</span> (renvoi <span class=\"kw-chiffre\">item 365</span>).<br><strong>Déplacement secondaire / fracture péri-prothétique :</strong> <span class=\"kw-ttt\">reprise chirurgicale</span>.</p>","hospit":"<p><strong>Orientation chirurgicale :</strong> la plupart des complications relèvent d'une <span class=\"kw-ttt\">reprise au bloc</span> — <span class=\"kw-ttt\">reprise chirurgicale</span> (déplacement secondaire), <span class=\"kw-ttt\">changement de matériel ou de prothèse</span>, <span class=\"kw-ttt\">ostéosynthèse</span> d'une fracture péri-prothétique sur prothèse scellée.<br><strong><span class=\"kw-def\">Suivi</span> multidisciplinaire :</strong> <span class=\"kw-clinique\">chirurgien, médecin traitant, infirmière, kinésithérapeute</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Recrudescence de douleur post-opératoire non calmée par les antalgiques</span> → évoquer un <span class=\"kw-etio\">syndrome des loges</span> (<span class=\"kw-alerte\">urgence</span>)</li><li><span class=\"kw-clinique\">Fièvre</span> + <span class=\"kw-clinique\">aspect inflammatoire de la cicatrice</span> / signes locaux d'infection → <span class=\"kw-etio\">infection du site opératoire ou de prothèse</span> (la plus redoutée)</li><li><span class=\"kw-clinique\">Signes de TVP</span> du membre opéré → <span class=\"kw-etio\">maladie thrombo-embolique</span></li><li><span class=\"kw-clinique\">Douleur</span> + <span class=\"kw-clinique\">altération fonctionnelle</span> d'une prothèse → évoquer un <span class=\"kw-etio\">descellement</span></li><li><span class=\"kw-clinique\">Douleur à l'appui</span> + <span class=\"kw-clinique\">mobilité persistante du foyer</span> → évoquer une <span class=\"kw-etio\">pseudarthrose</span></li></ul>","principes":"<p>Chaque complication a une <span class=\"kw-ttt\">conduite chirurgicale</span> propre : retenir le mapping <strong>complication → geste</strong>.</p><p><strong>Complications d'<span class=\"kw-ttt\">ostéosynthèse</span></strong></p><p>osteosynthese</p><ul><li><strong>Déplacement secondaire</strong> (montage peu rigide / os de mauvaise qualité) → <span class=\"kw-ttt\">reprise chirurgicale</span></li><li><strong>Cal vicieux</strong> → <span class=\"kw-ttt\">ostéotomie de réaxation</span> (si mal supporté ou sujet jeune)</li><li><strong>Pseudarthrose aseptique</strong> → <span class=\"kw-ttt\">PEC des facteurs</span> (arrêt du tabac, équilibre du <span class=\"kw-etio\">diabète</span>), <span class=\"kw-ttt\">injection de moelle osseuse autologue</span>, puis <span class=\"kw-ttt\">chirurgie</span> (excision + <span class=\"kw-ttt\">modification du montage</span> + <span class=\"kw-ttt\">auto-greffe</span>) si échec ; <span class=\"kw-ttt\">PTH</span> si pseudarthrose du col fémoral</li><li><strong>Pseudarthrose septique</strong> → <span class=\"kw-ttt\">antibiothérapie probabiliste puis adaptée</span> aux <span class=\"kw-bio\">prélèvements per-opératoires</span> + <span class=\"kw-ttt\">exérèse des tissus infectés</span> + <span class=\"kw-ttt\">changement de l'ostéosynthèse</span> + reconstruction osseuse (<span class=\"kw-ttt\">greffe</span>)</li></ul><p><strong>Complications de prothèse</strong></p><p>prothese</p><ul><li><strong>Luxation</strong> → <span class=\"kw-ttt\">réduction sous AG en urgence</span> ; <span class=\"kw-imagerie\">TDM</span> si récidive (infection, positionnement) ; <span class=\"kw-ttt\">changement de prothèse</span> si instabilité</li><li><strong>Descellement</strong> → <span class=\"kw-ttt\">changement des implants</span></li><li><strong>Fracture péri-prothétique</strong> → <span class=\"kw-ttt\">ostéosynthèse</span> (prothèse scellée + capital osseux suffisant) ou <span class=\"kw-ttt\">changement de prothèse</span></li><li><strong>Raideur</strong> → <span class=\"kw-ttt\">rééducation</span> ; <span class=\"kw-ttt\">mobilisation sous AG</span> (avant la <span class=\"kw-chiffre\">6ᵉ semaine</span>) ; <span class=\"kw-ttt\">arthrolyse arthroscopique</span> (à partir du <span class=\"kw-chiffre\">3ᵉ mois</span>)</li><li><strong><span class=\"kw-alerte\">Rupture</span> d'implant</strong> → <span class=\"kw-ttt\">changement prothétique</span> + <span class=\"kw-ttt\">déclaration de matériovigilance</span></li><li><strong>Usure</strong> (<span class=\"kw-clinique\">indolore</span> tant qu'isolée) → <span class=\"kw-imagerie\">surveillance radiologique</span></li></ul>","suivi":"<p><strong><span class=\"kw-ttt\">Ostéosynthèse</span> :</strong> consultations de contrôle <span class=\"kw-chiffre\">J2, J7, J15, J21, J45, J90</span> ; <span class=\"kw-imagerie\">cal osseux radiologique dès J30</span> ; <span class=\"kw-ttt\">ablation du matériel</span> <span class=\"kw-alerte\">non obligatoire</span> — seulement si consolidation complète (<span class=\"kw-chiffre\">12–18 mois</span>), gêne, trouble fonctionnel ou infection (risque de <span class=\"kw-alerte\">fracture itérative</span>).<br><strong>Prothèse :</strong> <span class=\"kw-def\">suivi</span> <span class=\"kw-ttt\">multidisciplinaire</span> ; <span class=\"kw-chiffre\">HAS : suivi annuel pendant 5 ans puis biannuel</span> ; <span class=\"kw-imagerie\">RX</span> à la recherche d'un <span class=\"kw-imagerie\">liseré périprothétique + ostéolyse</span> (descellement) ; <span class=\"kw-imagerie\">TDM séquence MARS</span> si <span class=\"kw-clinique\">lésion</span> douteuse.</p>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/fracture-healing","label":"Radiopaedia — Fracture healing (consolidation)"},{"href":"https://radiopaedia.org/articles/complications-of-total-hip-arthroplasty","label":"Radiopaedia — Complications of total hip arthroplasty"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Complication de matériel orthopédique — Ostéosynthèse ou prothèse : conduite selon la complication","detail":"<h4>CAT devant une complication de matériel orthopédique — <span class=\"kw-ttt\">Ostéosynthèse</span> & prothèse — mapping complication → geste (fiche 362)</h4>","branches":[{"to":"t-loges","label":"Douleur post-op non calmée par antalgiques","color":"red"},{"to":"t-deplacement","label":"Déplacement secondaire","color":"amber"},{"to":"q-luxation","label":"Luxation de prothèse","color":"amber"},{"to":"q-pseudarthrose","label":"Absence de consolidation ≥ 6 mois","color":"amber"},{"to":"t-descellement","label":"Descellement (douleur + liseré/ostéolyse)","color":"amber"},{"to":"q-fracture","label":"Fracture péri-prothétique","color":"amber"}]},{"id":"t-loges","kind":"terminal","label":"Urgence chirurgicale (syndrome des loges) — Renvoi item 365","color":"red","detail":"<h4>Geste</h4><ul><li><span class=\"kw-alerte\">Urgence chirurgicale</span> sans délai</li><li>Évoqué devant une <span class=\"kw-clinique\">douleur post-opératoire non calmée par les antalgiques</span></li></ul>"},{"id":"t-deplacement","kind":"terminal","label":"Reprise chirurgicale — Déplacement secondaire","color":"amber","detail":"<h4>Mécanisme</h4><ul><li><span class=\"kw-etio\">Montage peu rigide</span> ou <span class=\"kw-etio\">os de mauvaise qualité</span></li></ul>"},{"id":"q-luxation","kind":"decision","label":"Luxation de prothèse — Hanche la plus touchée","branches":[{"to":"t-lux-reduc","label":"1er épisode","color":"green"},{"to":"t-lux-tdm","label":"Récidive","color":"amber"},{"to":"t-lux-change","label":"Instabilité","color":"red"}]},{"id":"t-lux-reduc","kind":"terminal","label":"Réduction sous AG en urgence — 1er temps","color":"green","detail":"<h4>Geste</h4><ul><li><span class=\"kw-ttt\">Réduction par manœuvre externe sous anesthésie générale</span></li></ul>"},{"id":"t-lux-tdm","kind":"terminal","label":"TDM — Si récidive","color":"amber","detail":"<h4>Objectif</h4><ul><li>Vérifier l'absence d'<span class=\"kw-etio\">infection</span></li><li>Contrôler le <span class=\"kw-clinique\">positionnement des implants</span></li></ul>"},{"id":"t-lux-change","kind":"terminal","label":"Changement de prothèse — Si instabilité prothétique","color":"red"},{"id":"q-pseudarthrose","kind":"decision","label":"Pseudarthrose (≥ 6 mois) — Cause septique à évoquer en priorité","branches":[{"to":"t-pa-septique","label":"Cause septique (priorité)","color":"red"},{"to":"t-pa-aseptique","label":"Aseptique","color":"amber"}]},{"id":"t-pa-septique","kind":"terminal","label":"PEC médico-chirurgicale septique","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">ATB probabiliste puis adaptée</span> aux <span class=\"kw-bio\">prélèvements per-opératoires</span></li><li><span class=\"kw-ttt\">Exérèse des tissus infectés</span></li><li><span class=\"kw-ttt\">Changement du matériel</span> + reconstruction par <span class=\"kw-ttt\">greffe</span></li></ul>"},{"id":"t-pa-aseptique","kind":"terminal","label":"PEC de la pseudarthrose aseptique","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">PEC des facteurs</span> (tabac, <span class=\"kw-etio\">diabète</span>)</li><li><span class=\"kw-ttt\">Injection de moelle osseuse autologue</span></li><li><span class=\"kw-ttt\">Chirurgie</span> (excision + <span class=\"kw-ttt\">auto-greffe</span> + modification du montage) si échec</li></ul>"},{"id":"t-descellement","kind":"terminal","label":"Changement des implants — Descellement","color":"amber","detail":"<h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">Liseré périprothétique évolutif</span> + <span class=\"kw-imagerie\">ostéolyse</span></li></ul>"},{"id":"q-fracture","kind":"decision","label":"Fracture péri-prothétique","branches":[{"to":"t-fracture-osteo","label":"Scellée + os suffisant","color":"green"},{"to":"t-fracture-change","label":"Descellée / os insuffisant","color":"amber"}]},{"id":"t-fracture-osteo","kind":"terminal","label":"Ostéosynthèse — Prothèse scellée + capital osseux suffisant","color":"green"},{"id":"t-fracture-change","kind":"terminal","label":"Changement de prothèse — Prothèse descellée / os insuffisant","color":"amber"}]},"cards":[{"i":"448a0b710d1a","n":362,"o":"362-1","u":"Définition","t":"Connaître la définition d’une ostéosynthèse, d’une prothèse","q":"Quelles sont les indications principales d'une prothèse articulaire ?","a":"<ul><li><strong>Arthrose</strong> primitive ou secondaire, lorsque les traitements médicaux et conservateurs sont dépassés.</li><li><strong>Fracture à risque de nécrose secondaire</strong> (ex : fracture du col fémoral).</li><li><strong>Fracture articulaire trop comminutive</strong> chez le sujet âgé.</li></ul>"},{"i":"77a27320c377","n":362,"o":"362-1","u":"Définition","t":"Connaître la définition d’une ostéosynthèse, d’une prothèse","q":"Quelles sont les deux modalités de réduction d'une fracture avant une ostéosynthèse et leurs conséquences principales ?","a":"<ul><li><strong>Réduction à foyer ouvert</strong> : implique un abord chirurgical et une manipulation directe des fragments. Elle permet une <strong>réduction plus anatomique</strong> mais entraîne un <strong>dépériostage</strong> et une fuite de l'hématome péri-fracturaire.</li><li><strong>Réduction à foyer fermé</strong> : réalisée par manœuvres externes, avec un abord chirurgical à distance du foyer. Elle permet de <strong>conserver l'hématome péri-fracturaire</strong>, favorable à la consolidation.</li></ul>"},{"i":"8ebf11d673d2","n":362,"o":"362-1","u":"Définition","t":"Connaître la définition d’une ostéosynthèse, d’une prothèse","q":"Quelle est la définition d'une prothèse articulaire (arthroplastie) ?","a":"<p>L'arthroplastie est le remplacement, total ou partiel, d'une articulation par une prothèse. C'est un <strong>traitement non conservateur</strong> de l'articulation.</p>"},{"i":"b551ef9cf6b1","n":362,"o":"362-1","u":"Définition","t":"Connaître la définition d’une ostéosynthèse, d’une prothèse","q":"Quels sont les trois grands types d'ostéosynthèse et leurs indications préférentielles ?","a":"<ul><li><strong>Latéro-corticale</strong> (plaques ou vissage simple) : indiquée principalement pour les <strong>fractures métaphysaires</strong>.</li><li><strong>Centromédullaire</strong> (clou) : indiquée principalement pour les <strong>fractures diaphysaires</strong> (fémur, humérus, tibia).</li><li><strong>Fixation externe</strong> (système rigide non implanté) : indiquée en cas de <strong>fractures ouvertes</strong> (couverture cutanée difficile/douteuse), d'<strong>état général précaire</strong> ou de <strong>damage control</strong> (en attente d'un clou ou d'une plaque).</li></ul>"},{"i":"ed2f9a060d08","n":362,"o":"362-1","u":"Définition","t":"Connaître la définition d’une ostéosynthèse, d’une prothèse","q":"Quelle est la définition d'une ostéosynthèse en traumatologie générale ?","a":"<p>L'ostéosynthèse est une technique chirurgicale de <strong>contention interne d'une fracture après réduction</strong> du foyer. Elle vise à :</p><ul><li>Assurer une contention interne après réduction de la fracture.</li><li>Permettre une mobilisation rapide du membre opéré en libérant les articulations sus- et sous-jacentes.</li></ul>"},{"i":"0cfb705d59ab","n":362,"o":"362-4","u":"Identifier une urgence","t":"Savoir rechercher les complications urgentes des ostéosynthèses (clinique, biologie, indication d’imagerie)","q":"Quelle est la présentation clinique d'une infection du site opératoire post-ostéosynthèse ?","a":"<p>Cliniquement, une infection du site opératoire se manifeste par :</p><ul><li>De la <strong>fièvre</strong>.</li><li>Une <strong>douleur</strong>.</li><li>Une cicatrice inflammatoire.</li><li>Un <strong>écoulement</strong>.</li><li>Une désunion de la cicatrice.</li></ul>"},{"i":"124851982d7a","n":362,"o":"362-4","u":"Identifier une urgence","t":"Savoir rechercher les complications urgentes des ostéosynthèses (clinique, biologie, indication d’imagerie)","q":"Comment diagnostiquer un syndrome des loges post-ostéosynthèse sur le plan clinique ?","a":"<p>Le diagnostic d'un syndrome des loges est avant tout <strong>clinique</strong> et repose sur :</p><ul><li>Une <strong>recrudescence de douleur post-opératoire non calmée par les antalgiques</strong>.</li><li>Une <strong>tension de la loge</strong>.</li><li>Une <strong>douleur à l'étirement passif</strong> des muscles de la loge concernée.</li></ul><p>La mesure des pressions de loge peut être réalisée en cas de doute, mais ne doit <strong>jamais retarder une éventuelle chirurgie</strong>.</p>"},{"i":"4fa0492eabb1","n":362,"o":"362-4","u":"Identifier une urgence","t":"Savoir rechercher les complications urgentes des ostéosynthèses (clinique, biologie, indication d’imagerie)","q":"Quels examens complémentaires sont indicatifs en cas de suspicion d'infection du site opératoire après une ostéosynthèse ?","a":"<p>En cas de suspicion d'infection du site opératoire, les examens complémentaires indicatifs sont :</p><ul><li>Une <strong>NFS</strong> et une <strong>CRP</strong> (biologie).</li><li>Des <strong>prélèvements locaux</strong> et des <strong>hémocultures</strong> pour identifier le germe (biologie).</li><li>Une <strong>radiographie de contrôle</strong>.</li><li>Autres imageries selon le contexte (IRM, TDM).</li></ul>"},{"i":"aeb8ba48255d","n":362,"o":"362-4","u":"Identifier une urgence","t":"Savoir rechercher les complications urgentes des ostéosynthèses (clinique, biologie, indication d’imagerie)","q":"Quels sont les signes cliniques et le contexte évocateurs d'une embolie graisseuse post-ostéosynthèse ?","a":"<p>L'embolie graisseuse survient typiquement dans un contexte de <strong>fracture d'os long</strong>. Les signes cliniques évocateurs sont :</p><ul><li>Une <strong>détresse respiratoire</strong>.</li><li>Des signes neurologiques.</li><li>Un <strong>purpura</strong>.</li></ul>"},{"i":"b69cb765b1e4","n":362,"o":"362-4","u":"Identifier une urgence","t":"Savoir rechercher les complications urgentes des ostéosynthèses (clinique, biologie, indication d’imagerie)","q":"Quand faut-il évoquer un déplacement secondaire d'ostéosynthèse et quels examens sont alors nécessaires ?","a":"<p>Un déplacement secondaire d'ostéosynthèse doit être évoqué devant :</p><ul><li>Une <strong>douleur</strong>.</li><li>Une <strong>déformation</strong>.</li><li>Une <strong>perte de réduction</strong>.</li></ul><p>Une <strong>radiographie de contrôle</strong> est indispensable pour évaluer le montage et la réduction.</p>"},{"i":"bde7f2410883","n":362,"o":"362-4","u":"Identifier une urgence","t":"Savoir rechercher les complications urgentes des ostéosynthèses (clinique, biologie, indication d’imagerie)","q":"Quelles sont les quatre complications urgentes des ostéosynthèses à dépister systématiquement en post-opératoire ?","a":"<p>Les quatre complications urgentes à dépister systématiquement en post-opératoire d'une ostéosynthèse sont :</p><ul><li>L'<strong>infection du site opératoire</strong>.</li><li>Le <strong>syndrome des loges</strong>.</li><li>L'<strong>embolie graisseuse</strong>.</li><li>La <strong>maladie thrombo-embolique</strong> (TVP/EP).</li></ul>"},{"i":"1250d320e219","n":362,"o":"362-6","u":"Prise en charge","t":"Savoir rechercher les complications urgentes des prothèses (clinique, biologie, indication d’imagerie)","q":"Quelles sont les complications urgentes principales à rechercher chez un patient porteur d'une prothèse articulaire ?","a":"<p>Les complications urgentes principales à rechercher chez un patient porteur d'une prothèse articulaire sont :</p><ul><li>L'<strong>infection de prothèse</strong>.</li><li>La <strong>luxation</strong> de prothèse.</li><li>La <strong>maladie thrombo-embolique</strong> (TVP/EP).</li><li>La <strong>fracture péri-prothétique</strong>.</li></ul>"},{"i":"2804013764a1","n":362,"o":"362-6","u":"Prise en charge","t":"Savoir rechercher les complications urgentes des prothèses (clinique, biologie, indication d’imagerie)","q":"Quels examens biologiques et d'imagerie faut-il réaliser en urgence pour confirmer une suspicion d'infection de prothèse articulaire ?","a":"<p>En cas de suspicion d'infection de prothèse articulaire, il faut réaliser en urgence :</p><ul><li>Une <strong>NFS</strong> et un dosage de la <strong>CRP</strong>.</li><li>Une <strong>ponction articulaire</strong> avec prélèvements pour documentation du germe.</li><li>Des <strong>hémocultures</strong>.</li><li>Une <strong>radiographie standard</strong> (recherche de liseré, ostéolyse).</li><li>Un <strong>scanner (TDM) avec séquence MARS</strong> si la radiographie est douteuse ou pour réduire les artefacts métalliques.</li></ul>"},{"i":"6921202246cf","n":362,"o":"362-6","u":"Prise en charge","t":"Savoir rechercher les complications urgentes des prothèses (clinique, biologie, indication d’imagerie)","q":"Comment se manifeste une luxation de prothèse articulaire et quelle est la première étape de sa prise en charge en urgence ?","a":"<p>Une luxation de prothèse articulaire se manifeste par :</p><ul><li>Une <strong>impotence fonctionnelle brutale</strong> du membre.</li><li>Une <strong>attitude vicieuse</strong> du membre.</li><li>Une <strong>douleur</strong>, particulièrement intense au niveau de la hanche.</li></ul><p>La première étape de la prise en charge est la <strong>réduction par manœuvre externe sous anesthésie générale</strong> en urgence. En cas de luxation récidivante, il faut éliminer une infection sous-jacente.</p>"},{"i":"b1a5d5a67b1f","n":362,"o":"362-6","u":"Prise en charge","t":"Savoir rechercher les complications urgentes des prothèses (clinique, biologie, indication d’imagerie)","q":"Quelle démarche adopter en cas de suspicion de maladie thrombo-embolique (TVP/EP) chez un patient porteur de prothèse ?","a":"<p>En cas de suspicion de maladie thrombo-embolique :</p><ul><li>Rechercher les <strong>signes de thrombose veineuse profonde (TVP)</strong> du membre opéré (douleur, œdème, chaleur).</li><li>Rechercher les <strong>signes d'embolie pulmonaire (EP)</strong> (dyspnée, douleur thoracique, tachycardie).</li><li>Les <strong>D-dimères</strong> peuvent être mesurés selon le contexte clinique.</li><li>L'<strong>écho-Doppler veineux</strong> est l'examen de choix pour la TVP.</li><li>L'<strong>angio-TDM pulmonaire</strong> est indiquée en cas de forte suspicion d'embolie pulmonaire.</li></ul>"},{"i":"b4a2bb602e26","n":362,"o":"362-6","u":"Prise en charge","t":"Savoir rechercher les complications urgentes des prothèses (clinique, biologie, indication d’imagerie)","q":"Quels sont les signes cliniques et la démarche diagnostique pour une fracture péri-prothétique en urgence ?","a":"<p>Les signes cliniques d'une fracture péri-prothétique sont :</p><ul><li>Un <strong>traumatisme</strong>.</li><li>Une <strong>douleur intense</strong> et une <strong>déformation</strong> en regard de la pièce prothétique.</li></ul><p>La démarche diagnostique en urgence inclut un <strong>bilan pré-opératoire</strong> complété par une <strong>radiographie standard</strong>, et éventuellement un <strong>scanner (TDM)</strong> pour évaluer un descellement associé ou le capital osseux.</p>"},{"i":"b9d68a3f8b57","n":362,"o":"362-6","u":"Prise en charge","t":"Savoir rechercher les complications urgentes des prothèses (clinique, biologie, indication d’imagerie)","q":"Comment dépister cliniquement une infection de prothèse articulaire ?","a":"<p>Devant une prothèse articulaire, une infection doit être évoquée face à :</p><ul><li>Une <strong>douleur inhabituelle</strong>.</li><li>Une <strong>fièvre</strong>.</li><li>Des signes inflammatoires locaux (<strong>chaleur, rougeur, œdème</strong>).</li><li>Un <strong>écoulement</strong> ou une <strong>fistule</strong> au niveau de la cicatrice.</li><li>Toute <strong>luxation précoce</strong> doit également faire évoquer une infection de principe.</li></ul>"},{"i":"dc95e40d33ad","n":362,"o":"362-6","u":"Prise en charge","t":"Savoir rechercher les complications urgentes des prothèses (clinique, biologie, indication d’imagerie)","q":"Quelle attitude adopter concernant la documentation bactériologique et l'antibiothérapie en cas d'infection ou de luxation précoce de prothèse ?","a":"<p>Toute infection ou luxation précoce de prothèse impose de <strong>documenter le germe par ponction/prélèvements</strong> avant d'instaurer une antibiothérapie, afin d'optimiser l'efficacité du traitement.</p>"},{"i":"ecdfda51b350","n":362,"o":"362-6","u":"Prise en charge","t":"Savoir rechercher les complications urgentes des prothèses (clinique, biologie, indication d’imagerie)","q":"Quels examens complémentaires sont indiqués en urgence pour diagnostiquer une luxation de prothèse et pour rechercher les causes de récidive ?","a":"<p>Pour diagnostiquer une luxation de prothèse, la <strong>radiographie standard</strong> est l'examen de référence en urgence.</p><p>En cas de luxation récidivante, un <strong>scanner (TDM)</strong> est indiqué pour évaluer le positionnement des implants et rechercher une éventuelle infection.</p>"}]};